import{_ as a,o,c as r,aV as t}from"./chunks/framework.BkhZod2m.js";const m=JSON.parse('{"title":"项目概览","description":"","frontmatter":{},"headers":[],"relativePath":"00-overview.md","filePath":"00-overview.md","lastUpdated":null}'),i={name:"00-overview.md"};function l(c,e,n,d,s,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="项目概览" tabindex="-1">项目概览 <a class="header-anchor" href="#项目概览" aria-label="Permalink to &quot;项目概览&quot;">​</a></h1><h2 id="qy-components-是什么" tabindex="-1">qy-components 是什么 <a class="header-anchor" href="#qy-components-是什么" aria-label="Permalink to &quot;qy-components 是什么&quot;">​</a></h2><p><code>qy-components</code> 是起印的多包前端基础仓库，集中维护通用 UI、表单能力、组合式 hooks、表格 schema/adapter、后台页面模式与主题，以及业务选择器和地址弹窗等包。它为不同业务消费者提供可发布的 Qy 能力，不承担任一消费者项目的完整应用架构。</p><p>当前技术事实是 Vue 3 + Element Plus 主 implementation。长期稳定面是 Qy interface、Qy schema、Qy tokens 和宿主 runtime；这不表示仓库已支持 Naive UI、React 或另一套 renderer。</p><h2 id="做什么与不做什么" tabindex="-1">做什么与不做什么 <a class="header-anchor" href="#做什么与不做什么" aria-label="Permalink to &quot;做什么与不做什么&quot;">​</a></h2><ul><li>维护有明确包边界的公共能力，并以各包源码、<code>package.json</code>、exports、测试和发布产物作为当前事实来源。</li><li>让 Qy 公开契约和业务使用方式与当前底层 implementation 保持可演进的边界。</li><li>为包、消费者与迁移建立可追溯的长期文档入口，同时保留历史 PRP 作为一次执行的输入。</li><li>不在文档治理中修改生产源码、公共类型、exports、依赖、锁文件、版本、构建、发布脚本或 npm 状态。</li><li>不因未来可能存在第二个 renderer 而预先引入 <code>framework</code> 参数、provider、注册器、多构建入口或机械的 adapter 目录。</li></ul><h2 id="权威顺序" tabindex="-1">权威顺序 <a class="header-anchor" href="#权威顺序" aria-label="Permalink to &quot;权威顺序&quot;">​</a></h2><ol><li>源码、<code>package.json</code>、exports、测试和发布产物决定当前事实。</li><li>根协作入口（仓库内 <code>AGENTS.md</code>）决定稳定铁律与任务路由。</li><li><a href="./01-architecture">架构</a> 与当前 ADR 决定长期架构和取舍。</li><li>包 README 描述当前公开使用方式。</li><li>迁移和消费者文档记录来源差异与接入证据。</li><li>PRP 描述一次实施；执行完成后，长期文档和 release record 承接结果。</li></ol><h2 id="相关消费者的角色" tabindex="-1">相关消费者的角色 <a class="header-anchor" href="#相关消费者的角色" aria-label="Permalink to &quot;相关消费者的角色&quot;">​</a></h2><p><code>qy-permission</code> 是后台标准页和权限消费者，<code>qy-origin-app</code> 是录单及业务公共包消费者，<code>qy-workspace</code> 是旧 ERP 行为、使用频率和迁移证据来源。三者不是同一层级的版本权威：实际安装与解析结果始终由各消费者自己的 <code>package.json</code> 和 lockfile 决定。</p><p>关于包层级、公开 interface、主题、runtime/adapter、exports、发布与消费者关系，请继续阅读 <a href="./01-architecture">架构</a>。</p>',11)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
